def hook(ctx, nb):
    stage = nb.get('stage', '')
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    verb = nb.get('required_verb') or needverb(nb.get('task_type', ''))
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal object; recover by setting it aside only if needed, then find and take the requested target type.'
    elif stage == 'take_target' and target:
        msg = 'A requested target type is available here. Take a ' + target + ' instead of continuing to search or examining unrelated objects.'
    elif stage == 'transform' and target and verb:
        place = 'sinkbasin'
        if verb == 'heat':
            place = 'microwave'
        if verb == 'cool':
            place = 'fridge'
        if verb == 'slice':
            place = 'knife'
        msg = 'You are carrying the target ' + target + '. Before placing it, use the admissible ' + verb + ' action at the ' + place + ' or with the ' + place + '.'
    elif stage == 'put_target' and target and dest:
        msg = 'You are at the destination with the target ' + target + '. Use the admissible put action for ' + dest + ', not a different receptacle.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the target ' + target + ' to a ' + dest + ' and put it there; avoid taking unrelated objects.'
    elif stage == 'find_target' and target and (val(ctx, 'predicates.same_action_repeated', False) or val(ctx, 'predicates.same_observation_repeated', False) or val(ctx, 'predicates.remaining_steps_low', False)):
        msg = 'Search unopened or unvisited containers for the target type ' + target + '. When its take action appears, choose it over other object types.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

