def hook(ctx, nb):
    target = nb.get('target_type') or text(val(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(val(ctx, 'task.destination_type', ''))
    tt = nb.get('task_type') or text(val(ctx, 'task.task_type', ''))
    act = text(val(ctx, 'action.final_action', val(ctx, 'action.normalized', val(ctx, 'action.raw', ''))))
    if not target or not act:
        return None
    if 'pick_two' in tt and act.startswith('take ') and target in act:
        items = val(ctx, 'world.placed_items', [])
        locs = val(ctx, 'world.placed_locations', [])
        bad = False
        if isinstance(items, (list, tuple, set)):
            for item in items:
                if text(item) and text(item) in act:
                    bad = True
        if isinstance(locs, (list, tuple, set)) and dest:
            for loc in locs:
                if text(loc) and text(loc) in act:
                    bad = True
        if bad:
            return {'kind': 'block_and_prompt', 'message': 'Do not take back a target already placed for the two-object task. Leave it there and find another target of the same type for the same destination.'}
    if act.startswith('put ') and target in act and dest and dest not in act:
        return {'kind': 'block_and_prompt', 'message': 'This is not the requested destination type. Carry the target to a ' + dest + ' and put it there instead.'}
    return None
